function verify(bool $ok,string $message):void{if(!$ok)throw new RuntimeException($message);}
function rejects(callable $fn,string $label):void{$bad=false;try{$fn();}catch(InvalidArgumentException $e){$bad=true;}verify($bad,$label);}
$pdo=db();$admin=['id'=>1,'role'=>'super_admin'];foundation_migrate($pdo);foundation_migrate($pdo);
verify((int)$pdo->query('SELECT COUNT(*) FROM employees')->fetchColumn()===2,'Existing employee backfill failed');verify((int)$pdo->query('SELECT COUNT(*) FROM roles')->fetchColumn()===6,'Default roles duplicated');
$pdo->exec("INSERT INTO departments(name) VALUES('Engineering'),('Operations')");$department=(int)$pdo->query("SELECT id FROM departments WHERE name='Engineering'")->fetchColumn();$other=(int)$pdo->query("SELECT id FROM departments WHERE name='Operations'")->fetchColumn();
$pdo->prepare('INSERT INTO designations(name,department_id) VALUES(?,?)')->execute(['Engineer',$department]);$designation=(int)$pdo->lastInsertId();$role=(int)$pdo->query("SELECT id FROM roles WHERE slug='employee'")->fetchColumn();
