$edit=array_merge($input,['id'=>$id,'version'=>$employee['version'],'mobile'=>'9876543210']);save_employee($pdo,$admin,$edit,[]);rejects(fn()=>save_employee($pdo,$admin,$edit,[]),'Stale profile write accepted');
rejects(fn()=>save_employee($pdo,$admin,array_merge($input,['department_id'=>$other]),[]),'Cross-department designation accepted');rejects(fn()=>save_employee($pdo,$admin,array_merge($input,['birth_date'=>'2026-02-30']),[]),'Invalid date accepted');
$rows=[['name'=>'Import Example','designation'=>'Analyst','phone'=>'1234567890','birth_date'=>'1995-05-02','blood_group'=>'B+','emergency_contact'=>'1234567891','source_status'=>'Pending']];[$created,$skipped]=import_foundation($pdo,$admin,$rows);verify($created===1&&$skipped===0,'Employee import failed');[$created,$skipped]=import_foundation($pdo,$admin,$rows);verify($created===0&&$skipped===1,'Import not idempotent');
$import=$pdo->query("SELECT u.*,e.employee_code,e.department_id,e.joining_date FROM users u JOIN employees e ON u.id=e.user_id WHERE u.username='import.example'")->fetch(PDO::FETCH_ASSOC);verify($import['employee_code']===null&&$import['email']===null&&$import['department_id']===null&&$import['joining_date']===null,'Import invented data');
verify(can($pdo,$admin,'roles.delete')&&!can($pdo,['id'=>2,'role'=>'employee'],'employees.edit'),'Default access failed');
$pdo->exec("INSERT INTO roles(name,slug) VALUES('Viewer','ci-viewer')");$viewer=(int)$pdo->lastInsertId();$pdo->exec("INSERT INTO role_permissions(role_id,permission_id) SELECT $viewer,id FROM permissions WHERE code IN ('dashboard.view','employees.view')");$pdo->prepare('UPDATE user_roles SET role_id=? WHERE user_id=?')->execute([$viewer,3]);verify(can($pdo,['id'=>3,'role'=>'employee'],'employees.view')&&!can($pdo,['id'=>3,'role'=>'employee'],'employees.edit'),'Custom permission failed');
$pdo->exec('UPDATE roles SET active=0 WHERE id='.$viewer);verify(!can($pdo,['id'=>3,'role'=>'employee'],'employees.view'),'Inactive role grants access');$pdo->exec('UPDATE roles SET active=1 WHERE id='.$viewer);
$edit=foundation_employee($pdo,$id);$edit['role_id']=$viewer;rejects(fn()=>save_employee($pdo,['id'=>2,'role'=>'employee'],$edit,[]),'Unauthorized role assignment accepted');
