$hash=$pdo->query('SELECT token_hash FROM password_resets ORDER BY id DESC LIMIT 1')->fetchColumn();verify($hash===hash('sha256',$mail['token']),'Reset token not hashed');apply_recovery($pdo,$mail['token'],'Changed-CI-Password-2026');rejects(fn()=>apply_recovery($pdo,$mail['token'],'Changed-CI-Again-2026'),'Token replay accepted');
$u=$pdo->query('SELECT * FROM users WHERE id='.$id)->fetch(PDO::FETCH_ASSOC);verify((int)$u['session_version']===1&&password_verify('Changed-CI-Password-2026',$u['password_hash']),'Reset did not revoke sessions');
$expired=bin2hex(random_bytes(32));$pdo->prepare('INSERT INTO password_resets(user_id,token_hash,expires_at) VALUES(?,?,DATE_SUB(NOW(),INTERVAL 1 MINUTE))')->execute([$id,hash('sha256',$expired)]);rejects(fn()=>apply_recovery($pdo,$expired,'Changed-CI-Password-2026'),'Expired token accepted');
